--- frontends/porch-mfe/tests/PorchApp.bridge.test.tsx (336 lines) ---
/**
 * PorchApp.bridge.test.tsx — two-way address-bar <-> route bridge for the
 * embedded (in-shell) Porch mount. Mirrors
 * `frontends/commons-mfe/tests/CommonsApp.bridge.test.tsx`'s shape for
 * Porch's own (much simpler, no id<->handle translation) path space.
 *
 * DRIVE (shell -> Porch):
 *  - path="" renders Feed; path="friends" renders Friends.
 *  - a deep path (e.g. "groups") driving back to path="" returns to Feed,
 *    not left on the prior route.
 *
 * EMIT (Porch -> shell):
 *  - Clicking a topbar tab, and clicking a left-rail nav link, both call
 *    onPathChange with the target path.
 *  - Echo guard: re-rendering with the same path calls onPathChange EXACTLY
 *    zero additional times (not just "wasn't called again" in spirit).
 *
 * No-infinite-loop regression via a local ControlledPorchApp harness that
 * mirrors onPathChange back into path (as the real shell does), asserting
 * BOUNDED emit counts rather than exact ones.
 *
 * Plus a console.error spy asserting the DRIVE/EMIT cycle never produces
 * React Router's "location pathname must begin with the portion of the URL
 * pathname that was matched by all parent routes" crash (the symptom of a
 * broken basename / an overridden <Routes location>), and a SOURCE guard
 * confirming PorchApp.tsx never uses that override and never hardcodes a
 * "/p/" mount-path literal.
 */

import { useState, type ReactElement } from "react";
import { render, screen, waitFor, within } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { MemoryRouter, Route, Routes } from "react-router-dom";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";

import PorchApp from "../src/PorchApp";
import porchAppSource from "../src/PorchApp.tsx?raw";
import { renderEmbedded, EMBEDDED_BASE, EXERCISE_ID } from "./utils/renderPorch";
import { __resetPorchSession, setPorchSession } from "../src/hooks/usePorchSession";

const LOCATION_PATHNAME_ERROR_PATTERN = /location pathname must begin with/i;

// usePorchSession's store is a module-level singleton — reset it after every
// test in this file so a session seeded by one test (or left "loading") can
// never leak into the next.
afterEach(() => {
  __resetPorchSession();
  vi.unstubAllGlobals();
});

// ─── DRIVE: shell -> Porch ────────────────────────────────────────────────────

describe("PorchApp bridge — path prop drives internal navigation (shell->Porch)", () => {
  it("path='' renders the Feed route", async () => {
    renderEmbedded({ path: "" });
    expect(
      await screen.findByRole("region", { name: m.porch_feed_label() }),
    ).toBeInTheDocument();
  });

  it("path='friends' renders the Friends route", async () => {
    renderEmbedded({ path: "friends" });
    expect(await screen.findByText(m.porch_friends_empty_title())).toBeInTheDocument();
  });

  it("a deep path (groups) driving back to '' returns to the Feed route, not left on groups", async () => {
    const { rerender } = renderEmbedded({ path: "groups" });

    expect(await screen.findByText(m.porch_groups_empty_title())).toBeInTheDocument();

    // Re-render with path="" — must drive all the way back to Feed.
    rerender(
      <MemoryRouter initialEntries={[EMBEDDED_BASE]}>
        <Routes>
          <Route
            path="/range/exercises/:id/env/*"
            element={
              <PorchApp basePath={EMBEDDED_BASE} exerciseId={EXERCISE_ID} path="" />
            }
          />
        </Routes>
      </MemoryRouter>,
    );

    expect(
      await screen.findByRole("region", { name: m.porch_feed_label() }),
    ).toBeInTheDocument();
    expect(screen.queryByText(m.porch_groups_empty_title())).not.toBeInTheDocument();
  });
});

// ─── EMIT: Porch -> shell ─────────────────────────────────────────────────────

describe("PorchApp bridge — onPathChange emits the canonical path (Porch->shell)", () => {
  it("clicking a topbar tab calls onPathChange with the target path", async () => {
    const user = userEvent.setup();
    const onPathChange = vi.fn<(p: string) => void>();
    renderEmbedded({ path: "", onPathChange });

    const tabs = await screen.findByRole("navigation", { name: m.porch_tabs_label() });
    await user.click(within(tabs).getByRole("link", { name: m.porch_nav_friends() }));

    await waitFor(() => {
      expect(onPathChange).toHaveBeenCalledWith("friends");
    });
  });

  it("clicking a left-rail nav link calls onPathChange with the target path", async () => {
    const user = userEvent.setup();
    const onPathChange = vi.fn<(p: string) => void>();
    renderEmbedded({ path: "", onPathChange });

    const nav = await screen.findByRole("navigation", { name: m.porch_nav_label() });
    await user.click(within(nav).getByRole("link", { name: m.porch_nav_events() }));

    await waitFor(() => {
      expect(onPathChange).toHaveBeenCalledWith("events");
    });
  });
});

// ─── Echo guard ─────────────────────────────────────────────────────────────────

describe("PorchApp bridge — echo guard", () => {
  it("does NOT call onPathChange again when re-rendered with the same incoming path", async () => {
    const onPathChange = vi.fn<(p: string) => void>();
    const { rerender } = renderEmbedded({ path: "", onPathChange });

    await screen.findByRole("region", { name: m.porch_feed_label() });

    // Re-render with the SAME path="" — must not call onPathChange at all.
    rerender(
      <MemoryRouter initialEntries={[EMBEDDED_BASE]}>
        <Routes>
          <Route
            path="/range/exercises/:id/env/*"
            element={
              <PorchApp
                basePath={EMBEDDED_BASE}
                exerciseId={EXERCISE_ID}
                path=""
                onPathChange={onPathChange}
              />
            }
          />
        </Routes>
      </MemoryRouter>,
    );

    await waitFor(() => {
      // give any effects a chance to run
    });

    expect(onPathChange).toHaveBeenCalledTimes(0);
  });
});

// ─── No-infinite-loop regression ──────────────────────────────────────────────

/**
 * ControlledPorchApp — holds `path` in React state and mirrors onPathChange
 * back into it, exactly like a real host shell does. Records every emitted
 * path into the shared `emits` array so the test can assert bounded counts.
 */
function ControlledPorchApp({ emits }: { readonly emits: string[] }): ReactElement {
  const [path, setPath] = useState("");
  return (
    <PorchApp
      basePath={EMBEDDED_BASE}
      exerciseId={EXERCISE_ID}
      path={path}
      onPathChange={(p: string) => {
        emits.push(p);
        setPath(p); // mirror, like the real shell
      }}
    />
  );
}

describe("PorchApp bridge — no infinite loop regression", () => {
  it("in-app navigation into a route and back to feed via prop-driven path converges (bounded call counts)", async () => {
    const user = userEvent.setup();
    const emits: string[] = [];

    render(
      <MemoryRouter initialEntries={[EMBEDDED_BASE]}>
        <Routes>
          <Route
            path="/range/exercises/:id/env/*"
            element={<ControlledPorchApp emits={emits} />}
          />
        </Routes>
      </MemoryRouter>,
    );

    await screen.findByRole("region", { name: m.porch_feed_label() });
    const emitsBeforeNav = emits.length;

    // In-app navigate into Groups by clicking the left-rail nav link.
    const nav = await screen.findByRole("navigation", { name: m.porch_nav_label() });
    await user.click(within(nav).getByRole("link", { name: m.porch_nav_groups() }));

    await screen.findByText(m.porch_groups_empty_title());

    const emitsAfterNav = emits.length;
    // At most 2 additional emits for the single in-app navigation step.
    expect(emitsAfterNav - emitsBeforeNav).toBeLessThanOrEqual(2);

    // Navigate back to Feed by clicking the nav link again.
    const navAgain = await screen.findByRole("navigation", { name: m.porch_nav_label() });
    await user.click(within(navAgain).getByRole("link", { name: m.porch_nav_feed() }));

    await screen.findByRole("region", { name: m.porch_feed_label() });

    const emitsAfterBack = emits.length;
    // The whole round trip (nav in + nav back) stays bounded — no runaway
    // growth from an echo loop.
    expect(emitsAfterBack - emitsBeforeNav).toBeLessThanOrEqual(4);
  });
});

// ─── No broken-basename crash ───────────────────────────────────────────────────

describe("PorchApp bridge — no React Router basename crash", () => {
  it("never logs the 'location pathname must begin with' symptom of a broken basename", async () => {
    const consoleErrorSpy = vi.spyOn(console, "error").mockImplementation(() => undefined);
    const onPathChange = vi.fn<(p: string) => void>();
    const user = userEvent.setup();

    const { rerender } = renderEmbedded({ path: "groups", onPathChange });
    await screen.findByText(m.porch_groups_empty_title());

    // Drive back to Feed, then emit forward again via a click, exercising
    // both directions of the bridge in one pass.
    rerender(
      <MemoryRouter initialEntries={[EMBEDDED_BASE]}>
        <Routes>
          <Route
            path="/range/exercises/:id/env/*"
            element={
              <PorchApp
                basePath={EMBEDDED_BASE}
                exerciseId={EXERCISE_ID}
                path=""
                onPathChange={onPathChange}
              />
            }
          />
        </Routes>
      </MemoryRouter>,
    );
    await screen.findByRole("region", { name: m.porch_feed_label() });

    const nav = await screen.findByRole("navigation", { name: m.porch_nav_label() });
    await user.click(within(nav).getByRole("link", { name: m.porch_nav_saved() }));
    await screen.findByText(m.porch_saved_empty_title());

    for (const call of consoleErrorSpy.mock.calls) {
      for (const arg of call) {
        expect(String(arg)).not.toMatch(LOCATION_PATHNAME_ERROR_PATTERN);
      }
    }

    consoleErrorSpy.mockRestore();
  });
});

// ─── #2869 session-aware chrome under the embedded shape ───────────────────────

describe("PorchApp bridge — session-aware composer/login chrome under the embedded shape", () => {
  it("embedded + signed in: the composer entry point renders, and path bridging still works", async () => {
    setPorchSession({
      character: { id: "char-embed-1", display_name: "Embedded Ada" },
      exercise: { id: EXERCISE_ID },
    });
    const user = userEvent.setup();
    const onPathChange = vi.fn<(p: string) => void>();

    renderEmbedded({ path: "", onPathChange });

    expect(
      await screen.findByRole("button", { name: m.porch_composer_trigger_label() }),
    ).toBeInTheDocument();

    const nav = await screen.findByRole("navigation", { name: m.porch_nav_label() });
    await user.click(within(nav).getByRole("link", { name: m.porch_nav_friends() }));

    await waitFor(() => {
      expect(onPathChange).toHaveBeenCalledWith("friends");
    });
  });

  it("embedded + signed out: the composer trigger's pill renders (not a bare login row), and the feed still renders", async () => {
    renderEmbedded({ path: "" });

    expect(
      await screen.findByRole("region", { name: m.porch_feed_label() }),
    ).toBeInTheDocument();
    expect(
      screen.getByRole("button", { name: m.porch_composer_trigger_label() }),
    ).toBeInTheDocument();
    expect(
      screen.queryByRole("button", { name: m.porch_account_log_in() }),
    ).not.toBeInTheDocument();
  });
});

// ─── Source guards ──────────────────────────────────────────────────────────────

describe("PorchApp bridge — source guards", () => {
  /**
   * Strip comments before scanning. PorchApp.tsx's own header documents both
   * bans by NAMING them (`<Routes location={...}>`, the "/p/" mount path), so
   * a raw scan matches the documentation rather than the code and the guard
   * fires on a file that is actually correct. Scanning the comment-free
   * source keeps the guard about what ships.
   */
  const porchAppCode = porchAppSource
    .replace(/\/\*[\s\S]*?\*\//g, "")
    .replace(/\/\/.*$/gm, "");

  it("never overrides <Routes> with a location prop", () => {
    expect(porchAppCode).not.toMatch(/<Routes\s[^>]*location=/);
  });

  it("contains no literal '/p/' mount-path reference", () => {
    expect(porchAppCode).not.toMatch("/p/");
  });

  it("the comment-stripper still leaves real JSX to scan", () => {
    // Guards the guard: if the stripper ever ate the whole file, both
    // assertions above would pass vacuously.
    expect(porchAppCode).toMatch(/<Routes>/);
  });
});


--- frontends/porch-mfe/tests/PorchApp.test.tsx (507 lines) ---
/**
 * PorchApp.test.tsx — coverage for PorchApp's own route table, the four
 * embedding shapes its props allow, and cross-cutting chrome/a11y
 * invariants (single toast host, skip-link position, two distinct nav
 * landmarks, the error boundary). The path bridge itself (DRIVE/EMIT
 * effects) is covered separately in PorchApp.bridge.test.tsx.
 *
 * The "session-aware composer/login chrome" describe block below is #2869's
 * integration coverage: it proves the feed renders in BOTH the
 * signed-out and signed-in states, and that the SAME composer trigger card
 * renders in both — clicking it opens the login modal when signed out and
 * the composer modal when signed in (see PorchApp.tsx's own module doc for
 * the full reasoning, modeled on
 * `range-mfe/src/components/kite/KiteApp.tsx`'s login-state-aware nav
 * tail).
 */

import { screen, waitFor, within } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { axe } from "vitest-axe";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";

import indexHtml from "../index.html?raw";
import { renderStandalone, renderEmbedded, EMBEDDED_BASE } from "./utils/renderPorch";
import { __resetPorchSession, setPorchSession } from "../src/hooks/usePorchSession";

/**
 * Node's `process` exposes an `unhandledRejection` event even under jsdom
 * (vitest's environment swap only replaces DOM globals, not `process`).
 * Mirrors `range-mfe/src/components/AnnouncementComposerForm.test.tsx`'s own
 * helper: a real, unhandled rejection from a fire-and-forget promise chain
 * (e.g. a `.finally()`-only handler with no `.catch()`) surfaces here even
 * though nothing in the render tree ever throws synchronously.
 */
type RejectionListener = (reason: unknown) => void;
const rejectionHub = (
  globalThis as unknown as {
    process: {
      on: (event: "unhandledRejection", l: RejectionListener) => void;
      off: (event: "unhandledRejection", l: RejectionListener) => void;
    };
  }
).process;

function stubUnauthenticatedFetch(): void {
  vi.stubGlobal(
    "fetch",
    vi.fn().mockResolvedValue({
      ok: true,
      status: 200,
      json: async () => ({ authenticated: false }),
    } as Response),
  );
}

// usePorchSession's store is a module-level singleton (see that hook's own
// doc) — reset it after every test in this file so a session seeded (or
// left "loading") by one test can never leak into the next.
afterEach(() => {
  __resetPorchSession();
  vi.unstubAllGlobals();
});

vi.mock("../src/hooks/usePorchClock", async () => {
  const actual = await vi.importActual<typeof import("../src/hooks/usePorchClock")>(
    "../src/hooks/usePorchClock",
  );
  return { ...actual, usePorchClock: vi.fn(actual.usePorchClock) };
});

import { usePorchClock } from "../src/hooks/usePorchClock";

const mockedUsePorchClock = vi.mocked(usePorchClock);

describe("document title", () => {
  it("declares <title>Porch — OmniCore Range</title> in index.html", () => {
    expect(indexHtml).toContain("<title>Porch — OmniCore Range</title>");
  });
});

// ─── The four embedding shapes ────────────────────────────────────────────────

describe("PorchApp — embedding shapes", () => {
  it("standalone (no props) renders without throwing", () => {
    expect(() => renderStandalone()).not.toThrow();
  });

  it("basePath + exerciseId only, no bridge props, renders without throwing", () => {
    expect(() => renderEmbedded()).not.toThrow();
  });

  it("basePath + path with NO onPathChange renders without throwing", () => {
    expect(() => renderEmbedded({ path: "" })).not.toThrow();
  });

  it("fully controlled (path + onPathChange) renders without throwing", () => {
    expect(() => renderEmbedded({ path: "", onPathChange: vi.fn() })).not.toThrow();
  });
});

// ─── Route table ───────────────────────────────────────────────────────────────

describe("PorchApp — route table", () => {
  it("renders the Feed route at the index path", async () => {
    renderStandalone({ initialEntry: "/" });
    expect(
      await screen.findByRole("region", { name: m.porch_feed_label() }),
    ).toBeInTheDocument();
  });

  it("renders the Friends route", async () => {
    renderStandalone({ initialEntry: "/friends" });
    expect(await screen.findByText(m.porch_friends_empty_title())).toBeInTheDocument();
  });

  it("renders the Groups route", async () => {
    renderStandalone({ initialEntry: "/groups" });
    expect(await screen.findByText(m.porch_groups_empty_title())).toBeInTheDocument();
  });

  it("renders the Events route", async () => {
    renderStandalone({ initialEntry: "/events" });
    expect(await screen.findByText(m.porch_events_empty_title())).toBeInTheDocument();
  });

  it("renders the Saved route", async () => {
    renderStandalone({ initialEntry: "/saved" });
    expect(await screen.findByText(m.porch_saved_empty_title())).toBeInTheDocument();
  });

  it("standalone: the feed alias redirects to the index (Feed) route", async () => {
    renderStandalone({ initialEntry: "/feed" });
    expect(
      await screen.findByRole("region", { name: m.porch_feed_label() }),
    ).toBeInTheDocument();
  });

  it("standalone: an unknown path redirects to the index (Feed) route", async () => {
    renderStandalone({ initialEntry: "/does-not-exist" });
    expect(
      await screen.findByRole("region", { name: m.porch_feed_label() }),
    ).toBeInTheDocument();
  });

  it("embedded: the feed alias redirects to the index (Feed) route", async () => {
    renderEmbedded({ initialEntry: `${EMBEDDED_BASE}/feed` });
    expect(
      await screen.findByRole("region", { name: m.porch_feed_label() }),
    ).toBeInTheDocument();
  });

  it("embedded: an unknown path redirects to the index (Feed) route", async () => {
    renderEmbedded({ initialEntry: `${EMBEDDED_BASE}/does-not-exist` });
    expect(
      await screen.findByRole("region", { name: m.porch_feed_label() }),
    ).toBeInTheDocument();
  });
});

// ─── Chrome invariants ──────────────────────────────────────────────────────────

describe("PorchApp — chrome invariants", () => {
  it("mounts exactly one toast viewport", () => {
    renderStandalone();
    expect(
      document.body.querySelectorAll('[data-slot="toast-viewport"]'),
    ).toHaveLength(1);
  });

  it("puts the skip link as the first focusable element in the DOM", () => {
    renderStandalone();
    const focusable = document.body.querySelectorAll<HTMLElement>(
      "a[href], button, input, [tabindex]",
    );
    expect(focusable.length).toBeGreaterThan(0);
    expect(focusable[0]).toHaveTextContent(m.common_skip_to_main());
    expect(focusable[0]).toHaveAttribute("href", "#porch-main");
  });

  it("renders exactly two navigation landmarks with distinct accessible names", () => {
    renderStandalone();
    const navs = screen.getAllByRole("navigation");
    expect(navs).toHaveLength(2);

    const names = navs.map((nav) => nav.getAttribute("aria-label"));
    expect(new Set(names).size).toBe(2);
    expect(names).toEqual(
      expect.arrayContaining([m.porch_nav_label(), m.porch_tabs_label()]),
    );
  });
});

// ─── Error boundary ─────────────────────────────────────────────────────────────

describe("PorchApp — error boundary", () => {
  it("renders the platform-unavailable copy when a child route throws", async () => {
    // The thrown error is expected — suppress React's error-boundary console
    // noise (both its own dev-mode logging and componentDidCatch's own
    // console.error) for the duration of this test only.
    const consoleErrorSpy = vi.spyOn(console, "error").mockImplementation(() => undefined);

    // NOT mockImplementationOnce: React retries a failed render before it
    // hands the error to the nearest boundary, so a single-shot throw is
    // swallowed by that retry and the boundary never trips. Because this
    // implementation is persistent, it MUST be reset at the end of the test
    // (below) or it leaks into every later test in the file — there is no
    // global restoreMocks in vite.config.ts.
    mockedUsePorchClock.mockImplementation(() => {
      throw new Error("boom");
    });

    renderStandalone({ initialEntry: "/" });

    expect(
      await screen.findByText(m.porch_platform_unavailable_title()),
    ).toBeInTheDocument();
    expect(screen.getByText(m.porch_platform_unavailable_body())).toBeInTheDocument();
    expect(screen.getByRole("alert")).toBeInTheDocument();
    expect(screen.queryByText(m.porch_feed_label())).not.toBeInTheDocument();

    // Restores the implementation passed to vi.fn(actual.usePorchClock) in the
    // module factory, so later tests get the real clock hook back.
    mockedUsePorchClock.mockReset();
    consoleErrorSpy.mockRestore();
  });
});

describe("PorchApp — accessibility", () => {
  it("has no axe violations on the default (Feed) render", async () => {
    const { container } = renderStandalone();
    expect(await axe(container)).toHaveNoViolations();
  });
});

// ─── #2869 session-aware composer/login chrome ─────────────────────────────

describe("PorchApp — session-aware composer/login chrome", () => {
  it("signed out: the feed still renders, with the composer trigger's pill (not a bare login box)", async () => {
    stubUnauthenticatedFetch();

    renderStandalone({ initialEntry: "/" });

    // The headline #2869 criterion: a logged-out reader still gets the feed.
    expect(
      await screen.findByRole("region", { name: m.porch_feed_label() }),
    ).toBeInTheDocument();
    // The composer slot renders `PorchComposerTrigger`'s real pill even
    // signed out (routed to the login modal, not a separate bare
    // `porch_account_log_in` rectangle) — see PorchApp.tsx's module doc.
    expect(
      screen.getByRole("button", { name: m.porch_composer_trigger_label() }),
    ).toBeInTheDocument();
    expect(
      screen.queryByRole("button", { name: m.porch_account_log_in() }),
    ).not.toBeInTheDocument();
  });

  it("signed in: the feed renders with the real compose entry point, and no login row in its place", async () => {
    setPorchSession({
      character: { id: "char-1", display_name: "Ada Lovelace" },
      exercise: { id: "ex-1" },
    });

    renderStandalone({ initialEntry: "/" });

    expect(
      await screen.findByRole("region", { name: m.porch_feed_label() }),
    ).toBeInTheDocument();
    expect(
      screen.getByRole("button", { name: m.porch_composer_trigger_label() }),
    ).toBeInTheDocument();
    expect(
      screen.queryByRole("button", { name: m.porch_account_log_in() }),
    ).not.toBeInTheDocument();
    // The same session drives the left-rail identity card too — one source
    // of truth, not two independently-fed copies.
    expect(screen.getAllByText("Ada Lovelace").length).toBeGreaterThan(0);
  });

  it("clicking the composer trigger while signed out opens the shared login modal", async () => {
    stubUnauthenticatedFetch();
    const user = userEvent.setup();

    renderStandalone({ initialEntry: "/" });
    await screen.findByRole("region", { name: m.porch_feed_label() });

    await user.click(screen.getByRole("button", { name: m.porch_composer_trigger_label() }));

    expect(
      await screen.findByRole("dialog", { name: m.porch_login_title() }),
    ).toBeInTheDocument();
  });

  it("logging out via the account menu reverts the chrome to the signed-out state", async () => {
    setPorchSession({
      character: { id: "char-2", display_name: "Grace Hopper" },
      exercise: { id: "ex-1" },
    });
    vi.stubGlobal(
      "fetch",
      vi.fn().mockResolvedValue({ ok: true, status: 200, json: async () => ({}) } as Response),
    );
    const user = userEvent.setup();

    renderStandalone({ initialEntry: "/" });
    await screen.findByRole("region", { name: m.porch_feed_label() });

    await user.click(screen.getByRole("button", { name: m.porch_account_menu_label() }));
    await user.click(screen.getByRole("menuitem", { name: m.porch_account_log_out() }));

    // The composer trigger's pill renders regardless of session state (see
