/**
 * a11y.test.tsx — whole-page axe coverage over every porch-mfe route, in
 * BOTH embedding shapes (standalone and embedded), plus an explicit
 * landmark-contract assertion.
 *
 * Five routes (Feed/index, Friends, Groups, Events, Saved) x two embedding
 * shapes (standalone via `renderStandalone`, embedded via `renderEmbedded`)
 * = ten renders. `PorchApp.test.tsx` already axe-checks the default
 * (standalone Feed) render as part of its own chrome-invariants coverage;
 * this file's job is the full matrix, not a duplicate of that one case.
 *
 * The landmark contract mirrors `PorchLayout.tsx`'s own header comment:
 * `PorchNav` (left rail, a plain `<div>` wrapper, NOT an `<aside>`) is one
 * named `navigation` landmark, `PorchTopTabs` (topbar) is a second, distinctly
 * named `navigation` landmark, the right rail is the page's one
 * `complementary` landmark, `PorchTopbar` is wrapped in the one `banner`
 * landmark, and `<main id="porch-main">` is the one `main` landmark.
 */

import { screen } from "@testing-library/react";
import { axe } from "vitest-axe";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";

import { renderStandalone, renderEmbedded, EMBEDDED_BASE } from "./utils/renderPorch";
import { __resetPorchSession, setPorchSession } from "../src/hooks/usePorchSession";

// usePorchSession's store is a module-level singleton — reset it after every
// test in this file so a session seeded by one test (or left "loading") can
// never leak into the next.
afterEach(() => {
  __resetPorchSession();
  vi.unstubAllGlobals();
});

const FEED_PATH = "";
const FRIENDS_PATH = "friends";
const GROUPS_PATH = "groups";
const EVENTS_PATH = "events";
const SAVED_PATH = "saved";

const ROUTE_PATHS = [FEED_PATH, FRIENDS_PATH, GROUPS_PATH, EVENTS_PATH, SAVED_PATH] as const;

const STANDALONE = "standalone";
const EMBEDDED = "embedded";
const SHAPES = [STANDALONE, EMBEDDED] as const;

function standaloneEntry(routePath: string): string {
  return routePath === "" ? "/" : `/${routePath}`;
}

function embeddedEntry(routePath: string): string {
  return routePath === "" ? EMBEDDED_BASE : `${EMBEDDED_BASE}/${routePath}`;
}

interface RenderedMatrixCase {
  readonly shape: (typeof SHAPES)[number];
  readonly routePath: (typeof ROUTE_PATHS)[number];
}

const MATRIX: readonly RenderedMatrixCase[] = SHAPES.flatMap((shape) =>
  ROUTE_PATHS.map((routePath) => ({ shape, routePath })),
);

function renderCase({ shape, routePath }: RenderedMatrixCase): ReturnType<typeof renderStandalone> {
  return shape === STANDALONE
    ? renderStandalone({ initialEntry: standaloneEntry(routePath) })
    : renderEmbedded({ initialEntry: embeddedEntry(routePath) });
}

function caseLabel({ shape, routePath }: RenderedMatrixCase): string {
  return `${shape} — "${routePath === "" ? "(index/Feed)" : routePath}"`;
}

describe("porch-mfe — whole-page axe over every route x embedding shape", () => {
  it.each(MATRIX.map((c) => [caseLabel(c), c] as const))(
    "%s has no axe violations",
    async (_label, testCase) => {
      const { container } = renderCase(testCase);
      // Let the route settle before scanning — every stub hook resolves
      // synchronously to an "empty" state, so `main` appearing is sufficient.
      await screen.findByRole("main");
      expect(await axe(container)).toHaveNoViolations();
    },
  );
});

describe("porch-mfe — landmark contract", () => {
  it.each(MATRIX.map((c) => [caseLabel(c), c] as const))(
    "%s exposes exactly one banner, one main, one complementary, and two distinctly-named navigation landmarks",
    async (_label, testCase) => {
      renderCase(testCase);
      await screen.findByRole("main");

      expect(screen.getAllByRole("banner")).toHaveLength(1);
      expect(screen.getAllByRole("main")).toHaveLength(1);
      expect(screen.getAllByRole("complementary")).toHaveLength(1);

      const navs = screen.getAllByRole("navigation");
      expect(navs).toHaveLength(2);

      const names = navs.map((nav) => nav.getAttribute("aria-label"));
      expect(new Set(names).size).toBe(2);
      expect(names).toEqual(
        expect.arrayContaining([m.porch_nav_label(), m.porch_tabs_label()]),
      );
    },
  );
});

// ─── #2869 session-aware composer/login chrome ─────────────────────────────

describe("porch-mfe — Feed route axe coverage across session state (#2869)", () => {
  it("has no axe violations on the Feed route while signed out (login row in the composer slot)", async () => {
    const { container } = renderStandalone({ initialEntry: "/" });
    await screen.findByRole("region", { name: m.porch_feed_label() });
    expect(await axe(container)).toHaveNoViolations();
  });

  it("has no axe violations on the Feed route while signed in (real compose entry point)", async () => {
    setPorchSession({
      character: { id: "char-a11y-1", display_name: "Rosalind Franklin" },
      exercise: { id: "ex-1" },
    });
    const { container } = renderStandalone({ initialEntry: "/" });
    await screen.findByRole("region", { name: m.porch_feed_label() });
    expect(await axe(container)).toHaveNoViolations();
  });
});


