/**
 * i18n-keys-consumed.test.ts — mechanical enforcement of "every shipped
 * `porch.json` key has a real `m.<key>()` consumer somewhere in
 * porch-mfe's own source", and the converse: every `m.porch_*(` call site
 * found in that source names a key that actually exists in `porch.json`.
 * Nothing else in the repo enforces either direction for this package — an
 * orphaned key ships translation work for copy nothing reads, and a
 * typo'd `m.porch_*()` call renders a raw, untranslated key string at
 * runtime instead of throwing at build time (paraglide's generated
 * `messages.ts` only exports functions for keys that exist, so a typo'd
 * call name would actually fail to compile — but a key that DOES exist
 * under a slightly-different, still-valid name would silently read the
 * wrong copy; this test still catches the never-consumed side of that).
 *
 * The key list is read from `../../messages/en-US/porch.json` (the
 * `../../messages/en-US/<slice>.json` import shape already established by
 * `platform-chrome/tests/messages-auth-parity.test.ts`). Source is scanned
 * via Vite's `import.meta.glob(..., { query: "?raw", import: "default",
 * eager: true })`, the same mechanism `tests/theme-tokens.test.ts` and
 * `tests/rtl-logical-props.test.ts` already use in this package.
 *
 * "Consumer" pattern note: the five `porch_nav_*` keys (feed/friends/groups/
 * events/saved) are consumed NOT as a direct `m.porch_nav_feed(...)` call
 * site, but as a bare function reference — `src/porchLinks.ts` stores
 * `label: m.porch_nav_feed` (no parens; its own header comment explains this
 * is deliberate: "label is deliberately a bare reference to a m.porch_nav_*
 * message function, never an inline arrow") — and it is `PorchNav`/
 * `PorchTopTabs` calling `link.label()` that actually invokes it. A pattern
 * requiring a literal trailing `(` right after the key name would flag those
 * five as orphaned even though they are real, working, intentionally-shaped
 * consumers — that would be a false positive, not a caught bug. The
 * "has a consumer" check below therefore matches `m.<key>` at a word
 * boundary (covers both the direct-call and the bare-reference shape); the
 * reverse check (every call site names a real key) still requires the
 * literal `(`, since that direction is specifically about a call expression
 * that would render a raw key string at runtime if mistyped.
 */

import porchMessages from "../../messages/en-US/porch.json";

const PORCH_KEYS = Object.keys(porchMessages);

const SRC = import.meta.glob("../src/**/*.{ts,tsx}", {
  query: "?raw",
  import: "default",
  eager: true,
}) as Record<string, string>;

// m.<identifier>( — restricted to the porch_ prefix so a match can't
// accidentally pick up some other package's message call.
const PORCH_CALL_PATTERN = /\bm\.(porch_[a-zA-Z0-9_]+)\s*\(/g;

function findAllPorchCallSites(source: string): string[] {
  return Array.from(source.matchAll(PORCH_CALL_PATTERN)).map((match) => match[1]);
}

describe("porch-mfe i18n — every shipped porch.json key has a consumer", () => {
  it("scans a non-empty set of source files (guards against a broken glob)", () => {
    // Without this guard, a glob that silently resolves to `{}` would make
    // every "has a consumer" assertion below vacuously true — see
    // `range-mfe/tests/tokens/noXMarkSurvives.test.ts:52-54` for the
    // precedent this mirrors.
    expect(Object.keys(SRC).length).toBeGreaterThan(0);
  });

  it("loaded a non-trivial key list from porch.json (guards the fixture itself)", () => {
    expect(PORCH_KEYS.length).toBeGreaterThan(0);
  });

  it.each(PORCH_KEYS)("key %s has at least one m.<key> consumer under src/", (key) => {
    // Word-boundary, not a trailing "(": accepts both a direct call
    // (`m.<key>(`) and a bare function-reference consumer (`m.<key>` passed
    // as a value, e.g. `src/porchLinks.ts`'s `label: m.porch_nav_feed`) —
    // see the file-header note above for why the bare-reference shape is a
    // real consumer here, not something to paper over.
    const pattern = new RegExp(`\\bm\\.${key}\\b`);
    const consumers = Object.entries(SRC)
      .filter(([, content]) => pattern.test(content))
      .map(([path]) => path);
    // Report which file(s), if any — an empty array here is exactly the
    // failure this test exists to catch, and the assertion message should
    // name the orphaned key on its own (via the %s title), not require
    // digging through a diff.
    expect(consumers.length).toBeGreaterThan(0);
  });
});

describe("porch-mfe i18n — every m.porch_*( call site names a real key", () => {
  it("every m.porch_*( call found under src/ corresponds to a key that exists in porch.json", () => {
    const keySet = new Set(PORCH_KEYS);
    const offenders: string[] = [];

    for (const [path, content] of Object.entries(SRC)) {
      for (const called of findAllPorchCallSites(content)) {
        if (!keySet.has(called)) {
          offenders.push(`${path} calls m.${called}(), which is not a key in porch.json`);
        }
      }
    }

    expect(offenders).toEqual([]);
  });

  it("found at least one m.porch_*( call site to check (guards against a pattern that matches nothing)", () => {
    const totalCallSites = Object.values(SRC).reduce(
      (count, content) => count + findAllPorchCallSites(content).length,
      0,
    );
    expect(totalCallSites).toBeGreaterThan(0);
  });
});


