/**
 * rtl-render.test.tsx — confirms porch-mfe's chrome holds its DOM/focus
 * order under `dir="rtl"`. RTL is a VISUAL flip only: `PorchLayout` uses no
 * CSS `order`/`grid-area` reordering (see its own header comment), so the
 * left rail must still precede `<main>` in DOM order, and the skip link must
 * still be the first focusable node, exactly as under LTR. This complements
 * `tests/rtl-logical-props.test.ts` (a static source scan for physical vs.
 * logical Tailwind utilities) with a real render under `dir="rtl"`.
 */

import { screen } from "@testing-library/react";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";

import { renderStandalone } from "./utils/renderPorch";
import { __resetPorchSession } from "../src/hooks/usePorchSession";

const MIRRORING_CLASS_PATTERN = /rtl:|-scale-x-100|scale-x-\[-1\]|transform.*scaleX\(-1\)/;

describe("porch-mfe under dir=\"rtl\"", () => {
  const originalDir = document.documentElement.dir;

  beforeEach(() => {
    document.documentElement.dir = "rtl";
  });

  afterEach(() => {
    document.documentElement.dir = originalDir;
    // usePorchSession's store is a module-level singleton — reset it so one
    // test's resolved session state can never leak into the next.
    __resetPorchSession();
  });

  it("keeps the left rail preceding <main> in DOM order (no visual-only reordering)", async () => {
    renderStandalone();
    await screen.findByRole("main");

    const nav = screen.getByRole("navigation", { name: m.porch_nav_label() });
    const leftRail = nav.parentElement;
    expect(leftRail).not.toBeNull();

    const main = screen.getByRole("main");

    const position = leftRail!.compareDocumentPosition(main);
    // DOCUMENT_POSITION_FOLLOWING (4): `main` comes after `leftRail` in the
    // document, i.e. the left rail still precedes it.
    // eslint-disable-next-line no-bitwise
    expect(position & Node.DOCUMENT_POSITION_FOLLOWING).toBe(Node.DOCUMENT_POSITION_FOLLOWING);
  });

  it("carries no mirroring class on the brand glyph — the mark is never mirrored in RTL", async () => {
    renderStandalone();
    await screen.findByRole("main");

    const brandLink = screen.getByRole("link", { name: m.porch_app_name() });
    const glyph = brandLink.querySelector("svg");
    expect(glyph).not.toBeNull();
    expect(glyph!.getAttribute("class") ?? "").not.toMatch(MIRRORING_CLASS_PATTERN);
  });

  it("keeps the skip link as the first focusable element in the DOM", async () => {
    renderStandalone();
    await screen.findByRole("main");

    const focusable = document.body.querySelectorAll<HTMLElement>(
      "a[href], button, input, [tabindex]",
    );
    expect(focusable.length).toBeGreaterThan(0);
    expect(focusable[0]).toHaveTextContent(m.common_skip_to_main());
    expect(focusable[0]).toHaveAttribute("href", "#porch-main");
  });
});


