/**
 * RTL guard — porch-mfe must use CSS logical properties (ms/me, ps/pe,
 * border-s/e, text-start/end, inset-inline) so the ar-AE RTL flip is
 * automatic. Physical directional Tailwind utilities (ml-/mr-/pl-/pr-/
 * left-/right-/border-l/border-r/rounded-l/rounded-r/text-left/text-right)
 * would NOT flip and are a layout bug under RTL.
 *
 * This is a static source scan, not a render test. Source files are read via
 * Vite's import.meta.glob (raw, eager) so the test needs no node:fs / node
 * types — it runs in the same jsdom/vite environment as every other test.
 *
 * Two deliberate blind spots this test does NOT cover:
 *   - inline `style={{...}}` props (only scans `className` lines)
 *   - src/styles/index.css itself (only scans src/**\/*.{ts,tsx})
 *
 * ONE deliberate divergence from frontends/kite-mfe/tests/rtl-logical-props.test.ts,
 * which this file is otherwise a copy of: `rounded-l` and `rounded-r` carry a
 * trailing \b here. Without it the alternation also matches `rounded-lg` — a
 * symmetric all-corners radius that is perfectly RTL-safe — and the only fix
 * available to a component author is to change the design (e.g. to rounded-xl)
 * to appease a false positive. kite-mfe never noticed because it uses no
 * `rounded-lg`. The physical utilities this is meant to catch are the
 * corner-scoped `rounded-l-*` / `rounded-r-*` forms, which still match, since
 * the `-` after the l/r is a non-word character.
 */

const PHYSICAL =
  /\b(ml-|mr-|pl-|pr-|left-\d|right-\d|border-l\b|border-r\b|rounded-l\b|rounded-r\b|text-left|text-right)/;

const sources = import.meta.glob("../src/**/*.{ts,tsx}", {
  eager: true,
  query: "?raw",
  import: "default",
}) as Record<string, string>;

test("no physical directional Tailwind classes (RTL safety)", () => {
  const offenders: string[] = [];
  for (const [path, content] of Object.entries(sources)) {
    content.split("\n").forEach((line, i) => {
      if (line.includes("className") && PHYSICAL.test(line)) {
        offenders.push(`${path}:${i + 1}`);
      }
    });
  }
  expect(offenders).toEqual([]);
});


