/**
 * src/styles/index.css — the ten `--porch-*` tokens (bg, surface, text,
 * text2, border, border-strong, accent, accent-ink, hover, chip) must be
 * declared in ALL THREE theme blocks:
 *
 *   1. `:root { ... }`                                    (light default)
 *   2. `[data-theme="dark"], .dark { ... }`                (explicit dark)
 *   3. `@media (prefers-color-scheme: dark) { :root:not([data-theme="light"]) { ... } }`
 *      (system-preference dark) — NOT a bare `:root`; nested so an explicit
 *      light-theme override beats the OS preference.
 *
 * A token present in only two of the three silently falls back (to
 * `initial`/unset) in whichever theming path is missing it — that's the
 * whole point of this test. The CSS content is read via Vite's `?raw` import
 * mechanism (see frontends/commons-mfe/tests/theme-tokens.test.ts, the mould
 * for this file's mechanism).
 */

import css from "../src/styles/index.css?raw";
import tailwindConfigSrc from "../tailwind.config.ts?raw";
import cogPresetSrc from "../../ui/tailwind.preset.ts?raw";

const PORCH_TOKENS = [
  { name: "porch-bg", light: "243 241 244", dark: "12 10 14" },
  { name: "porch-surface", light: "255 255 255", dark: "22 19 26" },
  { name: "porch-text", light: "25 23 34", dark: "236 232 240" },
  { name: "porch-text2", light: "96 90 107", dark: "154 147 163" },
  { name: "porch-border", light: "229 225 232", dark: "38 33 48" },
  { name: "porch-border-strong", light: "138 130 145", dark: "122 114 132" },
  { name: "porch-accent", light: "138 61 114", dark: "217 139 196" },
  { name: "porch-accent-ink", light: "255 255 255", dark: "20 16 26" },
  { name: "porch-hover", light: "247 245 248", dark: "28 24 34" },
  { name: "porch-chip", light: "244 233 241", dark: "37 26 36" },
] as const;

/**
 * extractBlock — returns the content of the first brace-balanced block whose
 * opening `{` appears at or after `fromIndex`, starting the scan at
 * `startMarker`. Handles the nested-brace case (the @media block wraps
 * another rule) by counting braces rather than matching to the first `}`.
 */
function extractBlock(source: string, startMarker: string, fromIndex = 0): string {
  const markerIndex = source.indexOf(startMarker, fromIndex);
  if (markerIndex === -1) {
    throw new Error(`marker not found: ${startMarker}`);
  }
  const openIndex = source.indexOf("{", markerIndex);
  if (openIndex === -1) {
    throw new Error(`no opening brace after marker: ${startMarker}`);
  }
  let depth = 0;
  for (let i = openIndex; i < source.length; i += 1) {
    if (source[i] === "{") depth += 1;
    if (source[i] === "}") {
      depth -= 1;
      if (depth === 0) {
        return source.slice(openIndex + 1, i);
      }
    }
  }
  throw new Error(`unbalanced braces after marker: ${startMarker}`);
}

describe("src/styles/index.css theme blocks", () => {
  it("has exactly three theme blocks (:root, [data-theme=dark], and the prefers-color-scheme media query)", () => {
    // Sanity-checks the fixture this suite depends on: exactly one of each
    // marker should exist in the file. Holds because the media block's
    // selector is `:root:not([data-theme="light"]) {`, which does not match
    // the bare `:root\s*\{` regex below.
    //
    // If a future second `[data-theme="dark"]` rule is ever added, the fix
    // is to pass `fromIndex` to `extractBlock`, NOT to loosen this count.
    const rootMatches = css.match(/:root\s*\{/g) ?? [];
    const darkThemeMatches = css.match(/\[data-theme="dark"\]/g) ?? [];
    const mediaMatches = css.match(/@media \(prefers-color-scheme: dark\)/g) ?? [];

    expect(rootMatches.length).toBe(1);
    expect(darkThemeMatches.length).toBe(1);
    expect(mediaMatches.length).toBe(1);
  });

  describe("(a) declaration in all three blocks", () => {
    it("declares every --porch-* token with its light RGB triple in the :root block", () => {
      const rootBlock = extractBlock(css, ":root {");
      for (const { name, light } of PORCH_TOKENS) {
        // Trailing semicolon is load-bearing: without it a longer value
        // (e.g. `--porch-border: 229 225 232 1` in a hypothetical alpha
        // variant) would satisfy a bare `toContain` check.
        expect(rootBlock).toContain(`--${name}: ${light};`);
      }
    });

    it('declares every --porch-* token with its dark RGB triple in the [data-theme="dark"], .dark block', () => {
      // The trailing comma is part of the marker and load-bearing: a
      // `:root[data-theme="dark"] {` transcription (the shape the source
      // mockup artifact uses) makes extractBlock throw "marker not found",
      // which is the deliberate backstop against transcribing that artifact
      // verbatim (its dark `--p-*` block sits under a different selector).
      const darkBlock = extractBlock(css, '[data-theme="dark"],');
      for (const { name, dark } of PORCH_TOKENS) {
        expect(darkBlock).toContain(`--${name}: ${dark};`);
      }
    });

    it("declares every --porch-* token with the SAME dark RGB triple inside the @media (prefers-color-scheme: dark) block, nested under :root:not([data-theme=\"light\"])", () => {
      const mediaBlock = extractBlock(css, "@media (prefers-color-scheme: dark) {");
      // Confirms the nested selector shape, not a bare :root — this is what
      // lets an explicit light-theme override beat the OS preference.
      expect(mediaBlock).toContain(':root:not([data-theme="light"])');
      for (const { name, dark } of PORCH_TOKENS) {
        expect(mediaBlock).toContain(`--${name}: ${dark};`);
      }
    });

    it("anti-transcription guard: neither dark block retains any token's light value", () => {
      const darkBlock = extractBlock(css, '[data-theme="dark"],');
      const mediaBlock = extractBlock(css, "@media (prefers-color-scheme: dark) {");
      for (const { light } of PORCH_TOKENS) {
        expect(darkBlock).not.toContain(light);
        expect(mediaBlock).not.toContain(light);
      }
    });

    it("maps every --porch-* token in tailwind.config.ts theme.extend.colors as rgb(var(...) / <alpha-value>)", () => {
      for (const { name } of PORCH_TOKENS) {
        const re = new RegExp(
          `"${name}":\\s*"rgb\\(var\\(--${name}\\)\\s*/\\s*<alpha-value>\\)"`,
        );
        expect(tailwindConfigSrc).toMatch(re);
      }
    });

    it("declares exactly the ten porch-* tokens and no orphans", () => {
      const declared = new Set(
        Array.from(css.matchAll(/--porch-[a-z0-9-]+/g)).map((match) => match[0].slice(2)),
      );
      const expected = new Set(PORCH_TOKENS.map((t) => t.name));
      expect(declared).toEqual(expected);
    });
  });

  describe("(b) declared tokens are consumed by a component", () => {
    const SRC = import.meta.glob("../src/**/*.{ts,tsx}", {
      query: "?raw",
      import: "default",
      eager: true,
    }) as Record<string, string>;

    it("scans a non-empty set of source files (guards against a broken glob)", () => {
      expect(Object.keys(SRC).length).toBeGreaterThan(0);
    });

    // EXPECTED TO BE RED right now: a sibling agent is concurrently building
    // the components under src/components/ that will consume these tokens.
    // Do not weaken/skip/it.todo these — the failures below are the
    // deliverable (see the report for which tokens are unconsumed as of
    // this writing).
    it.each(PORCH_TOKENS.map((t) => t.name))(
      "some source file applies a Tailwind utility using --%s",
      (name) => {
        // Trailing (?![\w-]) lookahead is essential: without it
        // `text-porch-accent-ink` would satisfy `porch-accent`.
        const re = new RegExp(
          `\\b(?:bg|text|border|ring|outline|fill|stroke|from|via|to|divide|placeholder|caret|decoration|shadow|accent)-${name}(?![\\w-])`,
        );
        const consumed = Object.values(SRC).some((content) => re.test(content));
        expect(consumed).toBe(true);
      },
    );
  });

  describe("(c) no cog-* leak / containment", () => {
    it("the shared preset never mentions porch", () => {
      expect(cogPresetSrc).not.toMatch(/porch/i);
    });

    it("every key in porch's theme.extend.colors starts with porch-", () => {
      const colorsBlock = extractBlock(tailwindConfigSrc, "colors: {");
      const keys = Array.from(colorsBlock.matchAll(/"([a-z0-9-]+)":/g)).map((match) => match[1]);
      expect(keys.length).toBeGreaterThan(0);
      for (const key of keys) {
        expect(key.startsWith("porch-")).toBe(true);
      }
    });

    it("porch's --cog-* declarations are a subset of the canonical cog-* namespace (porch invents no new cog-*)", () => {
      // Canonical cog-* names: every "cog-<name>" key declared anywhere in
      // the shared preset (theme.extend.colors and elsewhere — e.g. the
      // boxShadow "cog-focus-light"/"cog-focus-dark" pair). A porch-declared
      // --cog-X name is accepted if it EQUALS a canonical name, or EXTENDS
      // one with a "-suffix" (the same pattern the preset itself uses:
      // cog-border-dark-emphasized extends cog-border, cog-focus-light/-dark
      // extend cog-focus) — this is what legitimizes the pre-existing,
      // preset-orphaned `--cog-focus-halo` custom property that every MFE's
      // index.css ships (a box-shadow value consumed directly via `var()`,
      // not through a Tailwind color utility).
      const canonical = new Set(
        Array.from(cogPresetSrc.matchAll(/"(cog-[a-z0-9-]+)"/g)).map((match) => match[1]),
      );
      expect(canonical.size).toBeGreaterThan(0);

      const declaredCog = new Set(
        Array.from(css.matchAll(/--cog-[a-z0-9-]+/g)).map((match) => match[0].slice(2)),
      );

      for (const name of declaredCog) {
        const isCanonical =
          canonical.has(name) ||
          Array.from(canonical).some((base) => name.startsWith(`${base}-`));
        expect(isCanonical).toBe(true);
      }
    });
  });
});


