import { screen } from "@testing-library/react";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";

import { renderStandalone } from "./utils/renderPorch";
import { __resetPorchSession } from "../src/hooks/usePorchSession";

const THEME_STORAGE_KEY = "theme";

function resetHtmlThemeState(): void {
  document.documentElement.removeAttribute("data-theme");
  document.documentElement.classList.remove("dark");
  document.documentElement.style.colorScheme = "";
  try {
    window.localStorage.removeItem(THEME_STORAGE_KEY);
  } catch {
    // localStorage unavailable — nothing to clear
  }
}

beforeEach(() => {
  resetHtmlThemeState();
});

afterEach(() => {
  resetHtmlThemeState();
  // usePorchSession's store is a module-level singleton (PorchApp now reads
  // it for the composer/login chrome) — reset it so one test's resolved
  // session state can never leak into the next.
  __resetPorchSession();
});

function expectStructuralChrome(): void {
  expect(screen.getByRole("banner")).toBeInTheDocument();
  expect(screen.getByRole("main")).toBeInTheDocument();
  const navs = screen.getAllByRole("navigation");
  expect(navs).toHaveLength(2);
  const names = navs.map((nav) => nav.getAttribute("aria-label"));
  expect(names).toEqual(
    expect.arrayContaining([m.porch_nav_label(), m.porch_tabs_label()]),
  );
}

describe("ThemeProvider attribute flip — data-theme=\"dark\"", () => {
  it("applies data-theme=\"dark\" to <html> when localStorage.theme is persisted as dark, and renders the chrome structurally", async () => {
    window.localStorage.setItem(THEME_STORAGE_KEY, "dark");

    renderStandalone();
    await screen.findByRole("main");

    expect(document.documentElement.getAttribute("data-theme")).toBe("dark");
    expectStructuralChrome();
  });
});

describe("ThemeProvider attribute flip — data-theme=\"light\"", () => {
  it("applies data-theme=\"light\" to <html> when localStorage.theme is persisted as light, and renders the chrome structurally", async () => {
    window.localStorage.setItem(THEME_STORAGE_KEY, "light");

    renderStandalone();
    await screen.findByRole("main");

    expect(document.documentElement.getAttribute("data-theme")).toBe("light");
    expectStructuralChrome();
  });
});

describe("the third theming path — the .dark class Tailwind's darkMode config also honours", () => {
  it("renders the chrome structurally, and leaves a pre-existing .dark class untouched, when <html> carries it independently of ThemeProvider", async () => {
    // ThemeProvider's own applyTheme() never calls classList — this
    // simulates the class-based half of tailwind.config.ts's
    // `darkMode: ["class", '[data-theme="dark"]']` array, which some
    // consumer other than this ThemeProvider is free to drive.
    document.documentElement.classList.add("dark");

    renderStandalone();
    await screen.findByRole("main");

    // ThemeProvider must not have stripped a class it doesn't own.
    expect(document.documentElement.classList.contains("dark")).toBe(true);
    expectStructuralChrome();
  });

  it("the .dark class and ThemeProvider's own data-theme attribute coexist without one clobbering the other", async () => {
    document.documentElement.classList.add("dark");
    window.localStorage.setItem(THEME_STORAGE_KEY, "light");

    renderStandalone();
    await screen.findByRole("main");

    // ThemeProvider's persisted mode still wins on the attribute it owns...
    expect(document.documentElement.getAttribute("data-theme")).toBe("light");
    // ...while the externally-applied class is left exactly as it was.
    expect(document.documentElement.classList.contains("dark")).toBe(true);
    expectStructuralChrome();
  });
});



